<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Dune Line — Overnight train, Amber Basin → Neon Harbor</title>
<style>
/* ============================================================
   DUNE LINE — a night railway, painted entirely in code
   Type duet: Georgia (voice) + system mono (paperwork)
   Palette: dusk amber / bone paper / warm ink / signal jade
   ============================================================ */
:root{
  --amber-hi:#F3BC71;
  --amber:#DE7C33;
  --sienna:#B34A17;
  --sienna-deep:#7C2D0C;
  --ink:#201208;
  --ink-soft:#3A230F;
  --cream:#F4EBDA;
  --paper:#FBF4E4;
  --night:#171210;
  --night-2:#211812;
  --jade:#69F0B6;
  --jade-deep:#166B45;
  --hair:rgba(32,18,8,.18);
  --hair-l:rgba(244,235,218,.16);
  --serif:Georgia,"Times New Roman",serif;
  --mono:ui-monospace,"SF Mono",Menlo,Consolas,"Courier New",monospace;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  font-family:var(--serif);
  background:var(--cream);
  color:var(--ink);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
::selection{background:var(--jade);color:var(--night)}
:focus-visible{outline:2px solid var(--jade-deep);outline-offset:3px;border-radius:2px}
img,svg{display:block}
section{scroll-margin-top:76px}

.wrap{max-width:1200px;margin:0 auto;padding:0 clamp(20px,4vw,48px)}

/* ---------- shared type helpers ---------- */
.mono{font-family:var(--mono)}
.eyebrow{
  font-family:var(--mono);font-size:11px;letter-spacing:.22em;text-transform:uppercase;
  display:flex;align-items:center;gap:14px;
}
.eyebrow::after{content:"";height:1px;flex:0 0 46px;background:currentColor;opacity:.4}
.sec-head{display:flex;justify-content:space-between;align-items:flex-end;gap:32px;flex-wrap:wrap;margin-bottom:clamp(36px,5vw,64px)}
.sec-head h2{font-size:clamp(32px,4.2vw,54px);font-weight:400;letter-spacing:-.02em;line-height:1.08;margin-top:18px;max-width:16em}
.sec-head .aside{font-family:var(--mono);font-size:12px;letter-spacing:.06em;line-height:1.9;opacity:.62;text-align:right;max-width:270px}
@media(max-width:720px){.sec-head .aside{text-align:left}}

/* ---------- buttons ---------- */
.btn{
  font-family:var(--mono);font-size:12px;letter-spacing:.14em;text-transform:uppercase;
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 22px;border:1px solid var(--ink);background:transparent;color:var(--ink);
  cursor:pointer;border-radius:2px;text-decoration:none;
  transition:transform .18s ease,box-shadow .18s ease,background .18s,color .18s,border-color .18s;
}
.btn:hover{transform:translateY(-2px);box-shadow:0 6px 0 -2px rgba(32,18,8,.28)}
.btn:active{transform:translateY(0);box-shadow:none}
.btn.solid{background:var(--jade-deep);border-color:var(--jade-deep);color:var(--paper)}
.btn.solid:hover{background:#1B7F53;box-shadow:0 6px 0 -2px rgba(22,107,69,.45)}
.btn.on-dark{border-color:var(--jade);color:var(--jade)}
.btn.on-dark:hover{background:var(--jade);color:var(--night);box-shadow:0 6px 0 -2px rgba(105,240,182,.35)}

/* ---------- reveal on scroll ---------- */
.rv{opacity:0;transform:translateY(18px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1)}
.rv.on{opacity:1;transform:none}

/* ============================================================
   NAVIGATION
   ============================================================ */
nav{
  position:fixed;top:0;left:0;right:0;z-index:60;
  transition:background .35s ease,color .35s ease,box-shadow .35s;
  color:var(--ink);
}
nav .bar{max-width:1200px;margin:0 auto;padding:16px clamp(20px,4vw,48px);display:flex;align-items:center;gap:28px}
.brand{display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:14px;font-weight:700;letter-spacing:.24em;text-decoration:none;color:inherit}
.brand svg{stroke:currentColor}
nav .links{display:flex;gap:6px;margin-left:auto;list-style:none}
nav .links a{
  font-family:var(--mono);font-size:11px;letter-spacing:.16em;text-transform:uppercase;text-decoration:none;
  color:inherit;opacity:.75;padding:9px 12px;border-radius:2px;position:relative;transition:opacity .2s;
}
nav .links a:hover{opacity:1}
nav .links a.act{opacity:1}
nav .links a.act::after{content:"";position:absolute;left:12px;right:12px;bottom:4px;height:2px;background:var(--jade-deep)}
nav.scrolled{background:rgba(23,18,16,.94);color:var(--cream);backdrop-filter:blur(8px);box-shadow:0 1px 0 rgba(244,235,218,.12)}
nav.scrolled .links a.act::after{background:var(--jade)}
nav .cta{padding:10px 16px}
.burger{display:none;margin-left:auto;background:none;border:1px solid currentColor;border-radius:2px;padding:8px;cursor:pointer;color:inherit}
.burger svg{stroke:currentColor}
@media(max-width:940px){
  nav .links{display:none;position:absolute;top:100%;left:0;right:0;flex-direction:column;background:rgba(23,18,16,.97);color:var(--cream);padding:10px 20px 22px;gap:2px}
  nav .links.open{display:flex}
  nav .links a{padding:13px 10px;border-bottom:1px solid rgba(244,235,218,.1);opacity:1}
  nav .links a.act::after{display:none}
  nav .cta{display:none}
  .burger{display:block}
}

/* ============================================================
   HERO — the full-bleed SVG dusk
   ============================================================ */
header.hero{position:relative;min-height:min(94vh,880px);overflow:hidden;background:var(--amber-hi)}
.scene{position:absolute;inset:0;width:100%;height:100%}
.scene g[data-depth],.scene .plx{will-change:transform}
.hero-inner{position:relative;z-index:2;display:grid;grid-template-columns:1.2fr .8fr;gap:clamp(32px,5vw,72px);align-items:start;padding-top:clamp(120px,16vh,180px);padding-bottom:220px}
.hero h1{font-size:clamp(46px,6.4vw,88px);line-height:1.02;letter-spacing:-.025em;font-weight:400}
.hero h1 em{font-style:italic}
.hero h1 .neo{color:var(--jade-deep)}
.hero .lede{max-width:34em;margin-top:26px;font-size:clamp(16px,1.4vw,19px);color:var(--ink-soft)}
.factstrip{display:flex;flex-wrap:wrap;gap:10px 0;margin-top:34px;font-family:var(--mono);font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-soft)}
.factstrip span{display:flex;align-items:center}
.factstrip span:not(:first-child)::before{content:"";width:26px;height:1px;background:var(--ink);opacity:.35;margin:0 14px}

/* boarding-pass card */
.pass{
  background:var(--paper);color:var(--ink);border:1px solid var(--hair);
  box-shadow:0 24px 50px -18px rgba(90,35,5,.45);
  transform:rotate(1.1deg);width:min(360px,100%);justify-self:end;
  font-family:var(--mono);position:relative;
}
.pass::after{ /* punch hole */
  content:"";position:absolute;top:50%;left:-9px;width:18px;height:18px;border-radius:50%;
  background:var(--amber-hi);transform:translateY(-50%);border:1px solid var(--hair);
}
.pass .p-head{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px dashed var(--hair)}
.pass .p-head b{letter-spacing:.2em;font-size:12px}
.pass .p-head span{font-size:10px;letter-spacing:.14em;opacity:.55}
.pass .p-route{display:flex;justify-content:space-between;align-items:baseline;padding:20px 20px 6px;font-size:22px;letter-spacing:.02em}
.pass .p-route i{font-style:normal;opacity:.4;font-size:14px}
.pass .p-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px 16px;padding:10px 20px 16px;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase}
.pass .p-meta small{display:block;font-size:9px;opacity:.5;margin-bottom:3px;letter-spacing:.2em}
.pass .p-count{margin:0 20px;padding:14px 0 12px;border-top:1px dashed var(--hair);text-align:center}
.pass .p-count small{display:block;font-size:9px;letter-spacing:.24em;opacity:.5;margin-bottom:6px}
.pass .p-count b{font-size:30px;font-weight:400;letter-spacing:.06em;color:var(--sienna-deep)}
.pass .p-foot{display:flex;justify-content:space-between;align-items:center;padding:12px 20px;border-top:1px dashed var(--hair);font-size:9.5px;letter-spacing:.1em;opacity:.75}
.barcode{display:flex;gap:2px;align-items:stretch;height:26px}
.barcode i{width:2px;background:var(--ink)}
.barcode i:nth-child(3n){width:4px}
.barcode i:nth-child(4n){opacity:.65}
.barcode i:nth-child(5n){width:1px}

/* --- SVG scene animation --- */
.star{animation:tw 4.4s ease-in-out infinite}
@keyframes tw{0%,100%{opacity:.2}50%{opacity:1}}
.win{animation:wfl 6.2s ease-in-out infinite}
@keyframes wfl{0%,88%,100%{opacity:1}92%{opacity:.55}96%{opacity:.85}}
.nwin{animation:nfl 7s ease-in-out infinite}
@keyframes nfl{0%,70%,100%{opacity:1}74%,80%{opacity:.35}}
.beacon{animation:bkl 2.4s ease-in-out infinite}
@keyframes bkl{0%,100%{opacity:.15}50%{opacity:1}}
.flock{animation:flk 26s ease-in-out infinite alternate}
@keyframes flk{from{transform:translate(0,0)}to{transform:translate(70px,-14px)}}
.rip{stroke-dasharray:26 38;animation:ripmove 9s linear infinite}
@keyframes ripmove{to{stroke-dashoffset:-256}}

@media(max-width:940px){
  .hero-inner{grid-template-columns:1fr;padding-top:130px;padding-bottom:180px}
  .pass{justify-self:start;transform:rotate(0)}
}

/* ============================================================
   FEATURES — a crew manifest, not a card row
   ============================================================ */
.features{padding:clamp(80px,10vw,140px) 0;background:var(--cream)}
.manifest{border-top:1px solid var(--ink)}
.row-feature{
  display:grid;grid-template-columns:120px 64px 1.05fr 1.6fr;gap:clamp(20px,3vw,48px);
  padding:clamp(30px,4vw,48px) 0;border-bottom:1px solid var(--hair);align-items:start;
  transition:background .25s;
}
.row-feature:hover{background:rgba(179,74,23,.05)}
.row-feature .idx{font-family:var(--mono);font-size:clamp(30px,3vw,42px);font-weight:700;color:var(--sienna);letter-spacing:-.04em;line-height:1}
.row-feature .glyph{color:var(--sienna);padding-top:6px}
.row-feature h3{font-size:clamp(21px,2.2vw,27px);font-weight:400;letter-spacing:-.01em;line-height:1.2}
.row-feature h3 small{display:block;font-family:var(--mono);font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;opacity:.5;margin-top:8px;font-weight:400}
.row-feature p{font-size:16px;color:var(--ink-soft);max-width:44em}
.row-feature p b{font-weight:400;color:var(--sienna-deep);font-style:italic}
@media(max-width:820px){
  .row-feature{grid-template-columns:56px 40px 1fr;grid-template-areas:"idx glyph ttl" "idx glyph body"}
  .row-feature .idx{grid-area:idx}.row-feature .glyph{grid-area:glyph}
  .row-feature h3{grid-area:ttl}.row-feature p{grid-area:body}
}

/* ============================================================
   TIMETABLE — the night board
   ============================================================ */
.board-sec{background:var(--night);color:var(--cream);padding:clamp(80px,10vw,140px) 0}
.board-sec .eyebrow{color:var(--jade)}
.board-sec .sec-head h2{color:var(--paper)}
.board-sec .aside{color:var(--cream)}
.clockface{color:var(--jade)!important;opacity:1!important;font-size:14px!important;letter-spacing:.1em!important}
.theboard{border-top:1px solid var(--hair-l);font-family:var(--mono)}
.trow{
  display:grid;grid-template-columns:82px 128px 100px 100px 120px 1fr;gap:16px;align-items:center;
  padding:20px 14px;border-bottom:1px solid var(--hair-l);cursor:pointer;position:relative;
  transition:background .2s,box-shadow .2s;
}
.trow.head{cursor:default;font-size:10px;letter-spacing:.2em;text-transform:uppercase;opacity:.45;padding:14px}
.trow:not(.head):hover{background:rgba(244,235,218,.05)}
.trow.sel{background:rgba(105,240,182,.07);box-shadow:inset 3px 0 0 var(--jade)}
.trow .svc{font-size:19px;letter-spacing:.06em;color:var(--paper)}
.trow .svc small{display:block;font-size:9px;letter-spacing:.2em;opacity:.45;margin-top:2px}
.trow .dep b{font-size:19px;font-weight:400;color:var(--paper)}
.trow .dep small,.trow .arr small{display:block;font-size:9.5px;letter-spacing:.14em;opacity:.5;margin-top:3px;text-transform:uppercase}
.trow .rel{font-size:10px;color:var(--jade);margin-top:2px;letter-spacing:.08em}
.trow .arr b{font-size:19px;font-weight:400;color:var(--paper)}
.trow .arr sup{font-size:10px;color:var(--jade);margin-left:2px}
.trow .dur{font-size:13px;opacity:.75}
.trow .fare{font-size:17px;color:var(--paper)}
.trow .fare small{font-size:9.5px;opacity:.5;display:block;letter-spacing:.16em}
.chip{
  justify-self:start;font-size:9.5px;letter-spacing:.18em;text-transform:uppercase;
  padding:6px 10px;border:1px solid rgba(244,235,218,.35);border-radius:20px;display:inline-flex;align-items:center;gap:7px;white-space:nowrap;
}
.chip.hot{border-color:#F2A15B;color:#F2A15B}
.chip.moon{border-color:var(--jade);color:var(--jade)}
.chip .dot{width:5px;height:5px;border-radius:50%;background:currentColor}
.pin-note{
  margin-top:22px;font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--jade);
  display:none;align-items:center;gap:12px;
}
.pin-note.show{display:flex}
.pin-note::before{content:"";width:34px;height:1px;background:var(--jade)}
@media(max-width:880px){
  .trow.head{display:none}
  .trow{grid-template-columns:1fr 1fr;gap:12px 20px;padding:22px 12px}
  .trow .svc{grid-column:1/-1}
  .trow .cell-label{display:block;font-size:9px;letter-spacing:.22em;text-transform:uppercase;opacity:.4;margin-bottom:3px}
}

/* ============================================================
   TESTIMONIAL — a postcard from km 884
   ============================================================ */
.notes-sec{background:var(--night);color:var(--cream);padding:10px 0 clamp(90px,11vw,150px)}
.postcard-zone{display:flex;justify-content:center;padding:20px 0 0}
.postcard{
  position:relative;background:var(--paper);color:var(--ink);max-width:660px;width:100%;
  padding:clamp(34px,5vw,58px) clamp(28px,5vw,60px);
  transform:rotate(-1.3deg);
  box-shadow:0 30px 60px -20px rgba(0,0,0,.6),0 2px 0 rgba(244,235,218,.08);
}
.postcard .tape{
  position:absolute;top:-13px;left:50%;width:110px;height:26px;transform:translateX(-50%) rotate(-2deg);
  background:rgba(244,235,218,.28);border:1px solid rgba(244,235,218,.12);
}
.postcard .corner{
  position:absolute;top:24px;right:28px;text-align:center;transform:rotate(4deg);
}
.postcard .corner .stamp{
  width:74px;height:88px;border:1px dashed var(--sienna);padding:6px;display:flex;align-items:center;justify-content:center;
}
.postcard .corner .mark{font-family:var(--mono);font-size:8.5px;letter-spacing:.14em;opacity:.6;margin-top:8px}
.postcard .qmark{font-size:74px;line-height:.6;color:var(--sienna);display:block;margin-bottom:18px;font-family:var(--serif)}
.postcard blockquote{font-size:clamp(20px,2.4vw,27px);font-style:italic;line-height:1.5;letter-spacing:-.01em}
.postcard figcaption{margin-top:26px;font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.62;line-height:2}
.postcard figcaption b{color:var(--sienna-deep)}
.jar{font-family:var(--mono);font-size:11px;letter-spacing:.2em;text-transform:uppercase;opacity:.45;text-align:center;margin-top:44px}
@media(max-width:640px){.postcard{transform:rotate(-.6deg)}.postcard .corner{top:14px;right:16px}}

/* ============================================================
   PRICING — the tariff sheet
   ============================================================ */
.fares{padding:clamp(80px,10vw,140px) 0;background:var(--cream)}
.fares .eyebrow{color:var(--sienna)}
.tiers{display:grid;grid-template-columns:1fr 1.18fr 1fr;gap:clamp(18px,2.4vw,30px);align-items:stretch}
.tier{border:1px solid var(--hair);background:var(--paper);padding:clamp(26px,3vw,38px);display:flex;flex-direction:column;border-radius:3px;transition:transform .25s,box-shadow .25s}
.tier:hover{transform:translateY(-4px);box-shadow:0 18px 36px -18px rgba(90,35,5,.3)}
.tier h3{font-size:24px;font-weight:400;letter-spacing:-.01em}
.tier .tag{font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;text-transform:uppercase;opacity:.55;margin-top:6px}
.tier .price{font-family:var(--mono);font-size:42px;letter-spacing:-.03em;margin:22px 0 4px;color:var(--ink)}
.tier .price sup{font-size:15px;vertical-align:super;opacity:.5}
.tier .per{font-family:var(--mono);font-size:10px;letter-spacing:.18em;text-transform:uppercase;opacity:.5}
.tier ul{list-style:none;margin:26px 0 30px;flex:1}
.tier li{position:relative;padding:9px 0 9px 26px;font-size:15px;color:var(--ink-soft);border-top:1px dotted var(--hair)}
.tier li::before{content:"—";position:absolute;left:0;font-family:var(--mono);color:var(--sienna)}
.tier.featured{
  background:var(--night-2);color:var(--paper);border-color:var(--night);
  position:relative;box-shadow:0 26px 48px -20px rgba(32,18,8,.5);
}
.tier.featured::before,.tier.featured::after{ /* ticket punch */
  content:"";position:absolute;width:26px;height:26px;border-radius:50%;background:var(--cream);
  top:calc(50% - 13px);
}
.tier.featured::before{left:-13px}
.tier.featured::after{right:-13px}
.tier.featured .flag{
  position:absolute;top:-13px;left:32px;background:var(--jade);color:var(--night);
  font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;padding:6px 12px;border-radius:2px;
}
.tier.featured h3{color:var(--paper)}
.tier.featured .tag{color:var(--jade);opacity:.9}
.tier.featured .price{color:var(--jade)}
.tier.featured li{border-top:1px dotted rgba(244,235,218,.2);color:rgba(244,235,218,.82)}
.tier.featured li::before{color:var(--jade)}
.cabins{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;margin:-8px 0 20px;opacity:.75}
.cabins b{color:var(--jade);font-weight:400}
.tier .btn{justify-content:center;width:100%}
.tier.featured .dashline{border-top:1px dashed rgba(244,235,218,.3);margin:0 -6px;padding-top:18px}
.smallprint{margin-top:34px;font-family:var(--mono);font-size:11px;letter-spacing:.06em;opacity:.55;display:flex;gap:8px;flex-wrap:wrap}
.smallprint span:not(:first-child)::before{content:"·";margin-right:8px}
@media(max-width:940px){
  .tiers{grid-template-columns:1fr;max-width:520px;margin:0 auto}
  .tier.featured::before,.tier.featured::after{top:auto;bottom:-13px;left:calc(50% - 13px)}
  .tier.featured::after{right:auto}
}

/* ============================================================
   FOOTER — arrival
   ============================================================ */
footer{background:#100C0A;color:var(--cream);padding:clamp(70px,9vw,120px) 0 0;position:relative;overflow:hidden}
.foot-grid{display:grid;grid-template-columns:1.3fr .7fr .9fr 1.1fr;gap:clamp(28px,4vw,56px);padding-bottom:70px}
.neonsign{display:inline-block;border:1px solid rgba(105,240,182,.5);border-radius:8px;padding:16px 26px 14px;position:relative;background:rgba(105,240,182,.04)}
.neonsign::before,.neonsign::after{content:"";position:absolute;width:1px;height:14px;background:rgba(244,235,218,.3);top:-14px}
.neonsign::before{left:22%}.neonsign::after{right:22%}
.neonsign b{
  font-family:var(--serif);font-style:italic;font-weight:700;font-size:clamp(24px,2.6vw,34px);
  letter-spacing:.06em;color:var(--jade);
  text-shadow:0 0 14px rgba(105,240,182,.5),0 0 2px rgba(105,240,182,.9);
}
.neonsign span{display:block;font-family:var(--mono);font-size:8.5px;letter-spacing:.3em;text-transform:uppercase;color:rgba(244,235,218,.45);margin-top:6px;text-shadow:none}
.foot-blurb{margin-top:26px;font-size:15px;color:rgba(244,235,218,.65);max-width:26em;line-height:1.7}
footer h4{font-family:var(--mono);font-size:10px;letter-spacing:.26em;text-transform:uppercase;color:var(--jade);margin-bottom:20px;font-weight:400}
footer ul{list-style:none}
footer ul li{margin-bottom:11px}
footer a.plainlink{color:rgba(244,235,218,.75);text-decoration:none;font-size:15px;border-bottom:1px solid transparent;transition:.2s}
footer a.plainlink:hover{color:var(--jade);border-bottom-color:var(--jade)}
footer address{font-style:normal;font-size:14px;line-height:2;color:rgba(244,235,218,.65)}
.nlform{display:flex;border:1px solid rgba(244,235,218,.3);border-radius:2px;overflow:hidden;margin-top:6px}
.nlform input{
  flex:1;min-width:0;background:transparent;border:0;padding:13px 14px;color:var(--paper);
  font-family:var(--mono);font-size:12.5px;letter-spacing:.05em;
}
.nlform input::placeholder{color:rgba(244,235,218,.35)}
.nlform input:focus{outline:none;background:rgba(244,235,218,.05)}
.nlform button{background:var(--jade);border:0;padding:0 16px;cursor:pointer;color:var(--night);display:flex;align-items:center;transition:.2s}
.nlform button:hover{background:#8FF5CB}
.nlmsg{font-family:var(--mono);font-size:11px;letter-spacing:.08em;margin-top:12px;color:var(--jade);min-height:16px}
.nlmsg.err{color:#F2A15B}
.shake{animation:shk .4s}
@keyframes shk{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}
.legal{
  border-top:1px solid var(--hair-l);padding:24px 0 26px;display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;
  font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:rgba(244,235,218,.4);
}
.sky-strip{position:absolute;left:0;right:0;bottom:44px;height:40px;opacity:.5;pointer-events:none}
@media(max-width:940px){.foot-grid{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.foot-grid{grid-template-columns:1fr}}

/* ---------- toast ---------- */
.toast{
  position:fixed;left:50%;bottom:30px;transform:translate(-50%,80px);z-index:100;
  background:rgba(23,18,16,.96);color:var(--paper);border-left:3px solid var(--jade);
  font-family:var(--mono);font-size:12.5px;letter-spacing:.05em;padding:15px 22px;border-radius:3px;
  box-shadow:0 18px 40px -12px rgba(0,0,0,.6);opacity:0;pointer-events:none;max-width:min(92vw,560px);
  transition:transform .45s cubic-bezier(.2,.9,.3,1.2),opacity .35s;
}
.toast.show{transform:translate(-50%,0);opacity:1}

@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001s!important;animation-iteration-count:1!important;transition-duration:.001s!important}
  html{scroll-behavior:auto}
  .rv{opacity:1;transform:none}
}
</style>
