      <div>
        <h4>Explore</h4>
        <ul>
          <li><a class="plainlink" href="#cars">The Cars</a></li>
          <li><a class="plainlink" href="#board">Departures</a></li>
          <li><a class="plainlink" href="#fares">Fares</a></li>
          <li><a class="plainlink" href="#notes">Field Notes</a></li>
        </ul>
      </div>
      <div>
        <h4>The Station</h4>
