<!-- toast -->
<div class="toast" id="toast" role="status" aria-live="polite"></div>

<script>
(function(){
"use strict";
const $=(s,c)=>{(c||document).querySelector(s)};
const $$=(s,c)=>Array.from((c||document).querySelectorAll(s));
const reduceMotion=matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------------- toast ---------------- */
let toastT;
function toast(msg){
  const t=$("#toast");
  t.textContent=msg;t.classList.add("show");
  clearTimeout(toastT);
  toastT=setTimeout(()=>t.classList.remove("show"),4200);
}

/* ---------------- clock ---------------- */
function pad(n){return String(n).padStart(2,"0")}
function tickClock(){
  const d=new Date();
  const el=$("#clock");
  if(el)el.textContent="LOCAL "+pad(d.getHours())+":"+pad(d.getMinutes())+":"+pad(d.getSeconds());
}
tickClock();setInterval(tickClock,1000);

/* ---------------- boarding-pass countdown to 21:15 ---------------- */
function nextAt(h,m){
  const d=new Date();d.setHours(h,m,0,0);
  if(d.getTime()<=Date.now())d.setDate(d.getDate()+1);
  return d;
}
const gateOpen=()=>nextAt(21,0), depAt=()=>nextAt(21,15);
function tickCd(){
  const diff=depAt()-Date.now(),open=gateOpen()-Date.now();
  const s=Math.max(0,Math.floor(diff/1000));
  const hh=Math.floor(s/3600),mm=Math.floor(s%3600/60),ss=s%60;
  const el=$("#countdown");
  el.textContent=pad(hh)+"H "+pad(mm)+"M "+pad(ss)+"S";
  // a whisper when the gate opens
  if(open<1500&&open>1450&&!window.__greeted){window.__greeted=true;toast("Gate B is open. Mind the sand on the gangway.");}
}
tickCd();setInterval(tickCd,1000);

/* ---------------- departure board ---------------- */
const SERVICES=[
  {n:"DL-01",h:19,m:40,arr:"07:05",dur:"11 h 25 m",plat:"Platform 1",fare:"$149",chip:["","On time"]},
  {n:"DL-02",h:21,m:15,arr:"08:32",dur:"11 h 17 m",plat:"Platform 3",fare:"$189",chip:["hot","Selling fast"],pop:true},
  {n:"DL-03",h:23,m:5,arr:"10:41",dur:"11 h 36 m",plat:"Platform 2",fare:"$214",chip:["moon","Full-moon run"]},
  {n:"DL-04",h:0,m:30,arr:"12:02",dur:"11 h 32 m",plat:"Platform 4",fare:"$129",chip:["","Red-eye · quiet coach"]}
];
let pinned=null;
const board=$("#boardRows");

// header row
const head=document.createElement("div");
head.className="trow head";
head.innerHTML='<span>Service</span><span>Departs · Basin</span><span>Arrives · Harbor</span><span>Journey</span><span>Fare from</span><span>Status</span>';
board.appendChild(head);

SERVICES.forEach(sv=>{
  const r=document.createElement("div");
  r.className="trow";r.setAttribute("role","option");r.tabIndex=0;r.dataset.n=sv.n;
  r.innerHTML=
    '<span class="svc">'+sv.n+(sv.pop?' <small>most boarded</small>':'<small>&nbsp;</small>')+'</span>'+
    '<span class="dep"><span class="cell-label">Departs</span><b>'+pad(sv.h)+':'+pad(sv.m)+'</b><small>'+sv.plat+'</small><span class="rel">—</span></span>'+
    '<span class="arr"><span class="cell-label">Arrives</span><b>'+sv.arr+'<sup>+1</sup></b><small>Central · Pier Esplanade</small></span>'+
    '<span class="dur"><span class="cell-label">Journey</span>'+sv.dur+'</span>'+
    '<span class="fare"><span class="cell-label">From</span>'+sv.fare+'<small>per person</small></span>'+
    '<span><span class="chip '+sv.chip[0]+'"><span class="dot"></span>'+sv.chip[1]+'</span></span>';
  r.addEventListener("click",()=>select(r,sv));
  r.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();select(r,sv);}});
  board.appendChild(r);
});

function select(row,sv){
  $$(".trow.sel",board).forEach(x=>x.classList.remove("sel"));
  row.classList.add("sel");
  pinned=sv.n;
  const note=$("#pinNote");
  note.classList.add("show");
  note.textContent=pinned+" pinned — fares below will follow it.";
}
function refreshRel(){
  $$(".trow",board).forEach(row=>{
    const sv=SERVICES.find(s=>s.n===row.dataset.n);if(!sv)return;
    const d=nextAt(sv.h,sv.m)-Date.now();
    const rel=$(".rel",row);if(!rel)return;
    const mins=Math.floor(Math.max(0,d)/60000);
    if(mins<=0){rel.textContent="departed";}
    else if(mins<60){rel.textContent="boards in "+mins+" min";}
    else{rel.textContent="boards in "+Math.floor(mins/60)+" h "+String(mins%60).padStart(2,"0")+" m";}
  });
}
refreshRel();setInterval(refreshRel,30000);

/* ---------------- hold-a-berth ---------------- */
let cabinsLeft=8;
const cabEl=$("#cabins");
$$(".hold-btn").forEach(btn=>{
  btn.addEventListener("click",()=>{
    if(btn.disabled){toast("Tonight's cabins are gone — DL-03 still has room. Try the board.");return;}
    const tier=btn.dataset.tier;
    let extra="";
    if(tier==="Starlight Cabin"){
      cabinsLeft--;
      cabEl.innerHTML="Cabins left tonight — <b>"+cabinsLeft+"</b>";
      if(cabinsLeft===0){
        cabEl.innerHTML="Cabins left tonight — <b>sold out</b>";
        btn.disabled=true;btn.textContent="Sold out tonight";
        extra=" That was the last one.";
      }
      if(pinned==="DL-02"){extra=" That's your pinned service."; }
    }
    toast("Berth held — "+tier+(pinned?" · "+pinned:" · any service")+". No card until you board."+extra);
  });
});

/* ---------------- nav ---------------- */
const nav=$("#nav");
addEventListener("scroll",()=>{nav.classList.toggle("scrolled",scrollY>50)},{passive:true});
const burger=$("#burger"),links=$("#navLinks");
burger.addEventListener("click",()=>{
  const open=links.classList.toggle("open");
  burger.setAttribute("aria-expanded",open);
});
$$("a",links).forEach(a=>a.addEventListener("click",()=>{
  links.classList.remove("open");burger.setAttribute("aria-expanded","false");
}));

/* active section highlight */
const map={};
$$("nav .links a").forEach(a=>{map[a.getAttribute("href").slice(1)]=a;});
const secObs=new IntersectionObserver(es=>{
  es.forEach(e=>{
    const a=map[e.target.id];if(!a)return;
    if(e.isIntersecting){$$("nav .links a").forEach(x=>x.classList.remove("act"));a.classList.add("act");}
  });
},{rootMargin:"-42% 0px -50% 0px"});
["cars","board","notes","fares"].forEach(id=>{const el=document.getElementById(id);if(el)secObs.observe(el);});

/* ---------------- reveal on scroll ---------------- */
const rvObs=new IntersectionObserver(es=>{
  es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("on");rvObs.unobserve(e.target);}});
},{threshold:.14});
$$("[data-reveal]").forEach(el=>{
  if(el.dataset.d)el.style.transitionDelay=el.dataset.d+"ms";
  rvObs.observe(el);
});

/* ---------------- hero parallax ---------------- */
if(!reduceMotion && matchMedia("(pointer:fine)").matches){
  const hero=$(".hero"),layers=$$(".plx",hero);
  let tx=0,ty=0,cx=0,cy=0;
  hero.addEventListener("pointermove",e=>{
    const r=hero.getBoundingClientRect();
    tx=((e.clientX-r.left)/r.width-.5)*2;
    ty=((e.clientY-r.top)/r.height-.5)*2;
  });
  hero.addEventListener("pointerleave",()=>{tx=0;ty=0;});
  (function lerp(){
    cx+=(tx-cx)*.06;cy+=(ty-cy)*.06;
    layers.forEach(g=>{
      const d=parseFloat(g.dataset.depth)||0;
      g.setAttribute("transform","translate("+(cx*d)+" "+(cy*d*.5)+")");
    });
    requestAnimationFrame(lerp);
  })();
}else{
  // static fallback: layers keep default transform
}

/* ---------------- newsletter ---------------- */
$("#nlForm").addEventListener("submit",e=>{
  e.preventDefault();
  const inp=$("#nlEmail"),msg=$("#nlMsg"),val=inp.value.trim();
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val)){
    msg.textContent="That address won't survive the postal run — check it?";
    msg.classList.add("err");
    inp.closest(".nlform").classList.remove("shake");
    void inp.offsetWidth;inp.closest(".nlform").classList.add("shake");
    return;
  }
  msg.classList.remove("err");
  msg.textContent="Noted. Next letter rides the DL-02.";
  inp.value="";
  toast("Subscribed — announcements, seasons only.");
});

/* ---------------- misc ---------------- */
$("#yr").textContent=new Date().getFullYear();
})();
</script>
</body>
</html>
```
